import{_ as e,o as a,c as r,a0 as o}from"./chunks/framework.B7o6dWmz.js";const c=JSON.parse('{"title":"什么是 NetonAPI","description":"","frontmatter":{},"headers":[],"relativePath":"zh-Hans/guide/what-is.md","filePath":"zh-Hans/guide/what-is.md","lastUpdated":1793979958000}'),i={name:"zh-Hans/guide/what-is.md"};function n(d,t,l,s,h,p){return a(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="什么是-netonapi" tabindex="-1">什么是 NetonAPI <a class="header-anchor" href="#什么是-netonapi" aria-label="Permalink to &quot;什么是 NetonAPI&quot;">​</a></h1><p>NetonAPI 是一个开源、自托管的大模型 API 中转站。你把采购来的上游账号（OpenAI、Anthropic、Google、国内厂商或别的中转站）接进来， 给自己的用户发 API Key、按 token 计费；用户用一个 Key 就能调用所有主流模型，官方 SDK 和 Claude Code 这类工具改个地址就能用。</p><p>它自带两个界面：</p><ul><li><strong>管理后台</strong>：给运营用。管渠道、管定价、给大客户谈价、看收入成本毛利、处理账务。</li><li><strong>网站与用户控制台</strong>：给买家用。注册登录、看模型与价格、创建 API Key、看用量与账单、充值。</li></ul><p><a href="https://neton.cloud" target="_blank" rel="noreferrer">Neton Cloud</a> 就是用 NetonAPI 运营的一个中转站，可以直接注册看看实际效果。</p><h2 id="和别的中转站有什么不一样" tabindex="-1">和别的中转站有什么不一样 <a class="header-anchor" href="#和别的中转站有什么不一样" aria-label="Permalink to &quot;和别的中转站有什么不一样&quot;">​</a></h2><p>大多数开源中转站从「把请求转出去」出发，计费是在转发上叠加几层倍率。 真正运营一个中转站，每天操心的是另外几件事：</p><ul><li>每个模型卖多少钱？拿货多少钱？这一单赚没赚？</li><li>给大客户打的折扣，会不会在某条渠道上卖亏？</li><li>用户看到的价格和他的账单对不对得上？</li></ul><p>NetonAPI 从一开始就围绕这几个问题设计：</p><table tabindex="0"><thead><tr><th>运营的问题</th><th>NetonAPI 的做法</th></tr></thead><tbody><tr><td>售价怎么定</td><td>以官方价为锚：售价 = 官方价 × 加价率；优惠写成「官方价 N 折」，官方价调整时自动跟随</td></tr><tr><td>拿货价是多少</td><td>每条渠道记录真实成本：官方价折扣、自动拉上游中转站的价目、或按模型手填</td></tr><tr><td>会不会卖亏</td><td>任何定价保存前按真实会走的每条渠道核算毛利，低于成本直接拒绝</td></tr><tr><td>账对不对得上</td><td>扣费 = tokens × 用户看到的单价，价格页、控制台、账单是同一个数</td></tr><tr><td>出了故障怎么办</td><td>先预留、后结算；进程崩溃自动恢复，说不清的账进人工复核，不会重复扣费</td></tr></tbody></table><h2 id="技术形态" tabindex="-1">技术形态 <a class="header-anchor" href="#技术形态" aria-label="Permalink to &quot;技术形态&quot;">​</a></h2><ul><li>服务端用 Kotlin/Native 编译成<strong>单个原生可执行文件</strong>，运行时不需要 JVM。</li><li>数据库只用 PostgreSQL；Redis 可选（多实例时共享限流）。</li><li>管理后台与网站前端是两个 Next.js 应用。</li><li>许可：Apache-2.0。</li></ul><p>下一步：<a href="./quick-start">快速开始</a> · <a href="./pricing">定价与毛利</a> · <a href="./features">功能一览</a></p>',13)])])}const _=e(i,[["render",n]]);export{c as __pageData,_ as default};
